# Thornwater (1v1): regenerated 2026-10-03 after the map-tools code review (H2: the old adoption stacked two Magpie Dens, two Lodges and a shrine on the peddler) with `run_world_forge.ps1 gen thornwater archetype=river_split players=2 tempo=standard biome=meadow count=40` (seed 4, spacing-checked; see docs/tools/world_forge/out/gen_thornwater/gen.md).
# generated: gen thornwater archetype=river_split seed=4 players=2 tempo=standard biome=meadow size=120 (do not hand-edit; copy to data/maps/<id>.map to adopt)
map thornwater  size=120  symmetry=rot180  biome=meadow  title="Thornwater (1v1)"  spec=docs/design/map-production.md
rules archetype=river_split  tempo=standard  players=2  seed=4  keep_enemy=116..150  natural=38..58  rich=65..95  crown=50..72  contest=5
seat 0  name="south-west"  side=0  frame=identity
seat 1  name="north-east"  side=1  frame=rot180

# base, expansions (templates; resource templates face the owner's keep)
use base_district  home  at=(-41.1,43.9)
use natural  nat  at=(-8.3,16.7)  yaw=-50.4
use rich_node  rich  at=(-40.1,-36.3)  yaw=-0.7

# centre and river
use crown_isle  centre  at=(0,0)  face=none
river arm  poly=[(-19.3,-61.9),(-15.8,-48.0),(-13.2,-36.6),(-10.8,-26.5),(-4.5,-19.0),(-3.9,-12.4)]  half_width=2.5
river arm2 poly=[(3.9,12.4),(4.5,19.0),(10.8,26.5),(13.2,36.6),(15.8,48.0),(19.3,61.9)]  half_width=2.5
moat center=(0,0)  radius=12.75  half_width=1.75
crossing bridge_road_a  kind=bridge_road  at=(-16.1,-49.1)  width=6  length=9  dir=(-1.0,0.2)
crossing bridge_road_b  kind=bridge_road  at=(16.1,49.1)  width=6  length=9  dir=(1.0,-0.2)
crossing ford_a  kind=ford  at=(-13.7,-38.8)  width=7  length=7  dir=(0.2,1.0)
crossing ford_b  kind=ford  at=(13.7,38.8)  width=7  length=7  dir=(0.2,1.0)
crossing bridge_crown_a  kind=bridge_lane  at=(-8.7,9.3)  width=8  length=6.5  dir=(-0.7,0.7)
crossing bridge_crown_b  kind=bridge_lane  at=(8.7,-9.3)  width=8  length=6.5  dir=(0.7,-0.7)
crossing steps_a  kind=steps  at=(-9.3,-8.7)  width=6  length=6  dir=(-0.7,-0.7)
crossing steps_b  kind=steps  at=(9.3,8.7)  width=6  length=6  dir=(0.7,0.7)

# capture points, camps, lairs
point tower_a  sub=watchtower  at=(-28.8,-40.4)
point tower_b  sub=watchtower  at=(-4.3,40.5)
point well     sub=well        at=(-31.8,-26.0)
point shrine   sub=shrine      at=(-17.5,2.3)
camp wallow  sub=bristleback  at=(-13.2,54.0)
use nest_in_ford  ford  at=(13.7,38.8)  face=none
camp stag  sub=hollow_stag  at=(-36.9,-8.2)
use lair_pair  lairs_w  at=(-51.4,-2.7)  yaw=133.2  a=tusker  b=roc
use lair_pair  lairs_n  at=(-45.0,-44.1)  yaw=223.2  a=direwolf  b=grizzlemaw

# services: tavern + peddler (contested axis), caches, guild houses, trade posts on the ring road
use tavern_peddler  inn  at=(-15.9,-13.4)  yaw=223.2
cache cache_a  at=(-28.1,-1.0)
cache cache_b  at=(-4.2,29.3)
post post_a  at=(-53.5,0.5)  door=(-51.6,4.1)
post post_b  at=(0.1,54.0)  door=(-3.5,52.2)
road ring  poly=[(-34.4,36.7),(-51.6,4.1),(-49.3,-42.4),(-45.5,-46.5),(3.5,-52.2),(34.4,-36.7)]  width=5
use guild_pair  guilds  at=(-51.0,-49.7)  yaw=45.7

# forest (the main.gd generator as data), bank willows, wildlife
forest seed=31683  pre=auto  density=1.00  pillars=(0,0,8)  pillar_count=10  pillar_gap=4
willows seed=141  draws=36  river_draws=28
slot graze0  sub=graze  at=(-23.1,-43.0)  clear=0
slot graze1  sub=graze  at=(-17.5,-47.4)  clear=0
slot graze2  sub=graze  at=(-25.9,-46.1)  clear=0
slot graze3  sub=graze  at=(-22.3,-52.9)  clear=0
slot rabbit0  sub=rabbit  at=(-11.4,27.3)  clear=0
slot rabbit1  sub=rabbit  at=(-26.6,21.5)  clear=0
slot rabbit2  sub=rabbit  at=(-20.7,34.4)  clear=0
slot rabbit3  sub=rabbit  at=(-33.4,34.2)  clear=0
use biome_meadow  ground  at=(-22.6,24.1)  face=none  r=22
